package dev.koikaster.mite;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.*;
/** Source stacks for the current tool production inputs; the remaining original catalogue stays explicit work. */
public final class ClassicStacks {
 public static int max(int original,Object rawStack){var stack=(ItemStack)rawStack;if(!ClassicToolCatalogue.sourceItem(stack))return original;Integer sourceCap=OriginalStackLimits.cap(stack);if(sourceCap!=null)return sourceCap;Integer blockCap=SourceBlockStacks206.cap(stack);if(blockCap!=null)return blockCap;Integer familyCap=SourceBlockFamilyStacks.cap(stack);if(familyCap!=null)return familyCap;if(stack.is(Items.SUGAR_CANE))return 16;if(stack.is(net.minecraft.tags.ItemTags.PLANKS)||stack.is(Items.BAMBOO_MOSAIC))return 8;if(stack.getItem() instanceof BlockItem shaped){var block=shaped.getBlock();if(block instanceof IronBarsBlock)return 16;if(block instanceof SlabBlock)return 8;if(block instanceof StairBlock)return 4;}var id=net.minecraftforge.registries.ForgeRegistries.ITEMS.getKey(stack.getItem());String name=id.getPath();if(stack.is(Items.ENCHANTING_TABLE)||stack.getItem() instanceof BlockItem table&&table.getBlock() instanceof OriginalEnchantingTables.EmeraldTable)return 4;if(stack.is(Items.ANVIL)||stack.is(Items.CHIPPED_ANVIL)||stack.is(Items.DAMAGED_ANVIL)||stack.getItem() instanceof BlockItem anvil&&anvil.getBlock() instanceof MetalAnvilBlock)return 1;if(java.util.Set.of("copper_block","silver_block","gold_block","iron_block","ancient_metal_block","mithril_block","adamantium_block","bronze_block","steel_block").contains(name))return 4;if(stack.is(Items.BUDDING_AMETHYST))return 4;if(stack.is(Items.BUCKET))return 8;if(stack.getItem() instanceof SpecialItems.MetalBucket bucket)return bucket.fluid(stack).isEmpty()?8:1;if(stack.is(Items.FURNACE)||stack.is(Items.SMOKER)||stack.is(Items.BLAST_FURNACE)||stack.is(Items.CAMPFIRE)||stack.is(Items.SOUL_CAMPFIRE)||stack.getItem() instanceof BlockItem block&&block.getBlock() instanceof ThermalFurnace.BlockImpl)return 1;if(stack.is(Items.SAND)||stack.is(Items.RED_SAND)||ClassicFurnaces.sandstone(stack)||stack.is(Items.GLASS)||stack.is(Items.TERRACOTTA)||stack.is(Items.CLAY)||stack.is(Items.CACTUS)||stack.is(Items.NETHERRACK)||stack.is(net.minecraft.tags.ItemTags.LOGS)||name.endsWith("_ore"))return 4;if(stack.is(Items.BRICK)||stack.is(Items.NETHER_BRICK))return 8;if(stack.is(Items.CLAY_BALL)||stack.is(Items.REDSTONE)||stack.is(Items.LAPIS_LAZULI)||stack.is(Items.QUARTZ)||stack.is(Items.BONE_MEAL)||stack.getItem() instanceof DyeItem)return 16;if(stack.is(Items.DIAMOND)||stack.is(Items.EMERALD))return 32;if(name.endsWith("_ingot"))return 8;if(stack.is(Items.COAL)||stack.is(Items.CHARCOAL)||stack.is(Items.BLAZE_ROD))return 16;if(stack.is(Items.STICK))return 32;if(stack.is(Items.STRING))return 32;if(name.equals("sinew"))return 16;if(stack.is(Items.ARROW)||stack.getItem() instanceof Tools.MetalArrow)return 16;return original;}
 /** Forge inserts into a zero-count destination copy: getItem() there is AIR. Use the still-live incoming identity for these changed caps. */
 public static int insertionMax(Object rawTarget,Object incoming){int original=((ItemStack)rawTarget).getMaxStackSize();return Math.min(original,((ItemStack)incoming).getMaxStackSize());}
 /** Native quick-move uses the empty slot's container limit without its incoming item. */
 public static int slotMax(Object rawSlot,Object incoming){return Math.min(((net.minecraft.world.inventory.Slot)rawSlot).getMaxStackSize(),((ItemStack)incoming).getMaxStackSize());}
 private ClassicStacks(){}
}
